const express = require('express');
const { trace } = require('@opentelemetry/api');

const app = express();
const cacheSpanStore = new Map();

app.get('/debug/spans/cache/:cacheSpanId', (req, res) => {
  if (!req.session || !req.session.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const span = cacheSpanStore.get(req.params.cacheSpanId);
  if (!span) {
    return res.status(404).json({ error: 'Cache span not found' });
  }

  // Assert tenant ownership on cache span attributes
  if (span.attributes['tenant.id'] !== req.session.tenantId) {
    return res.status(403).json({ error: 'Access denied to cross-tenant cache telemetry' });
  }

  res.json({
    cacheSpanId: req.params.cacheSpanId,
    cacheKey: span.attributes['cache.key'],
    hit: span.attributes['cache.hit'],
    serializedValueHash: span.attributes['cache.value_hash']
  });
});

app.listen(5051);
